onRecordCreateRequest(e=>{e.next();require(__hooks+'/audit-lib.js').write(e.app,e.record,e.auth,'create',{},require(__hooks+'/audit-lib.js').snapshot(e.record));},'students','classrooms','daycares','substitutions','menu_days','menu_items','users','lunch_requests','invoices','invoice_flags','school_notes');
onRecordUpdateRequest(e=>{const lib=require(__hooks+'/audit-lib.js'),before=lib.snapshot(e.record.original());e.next();lib.write(e.app,e.record,e.auth,'update',before,lib.snapshot(e.record));},'students','classrooms','daycares','substitutions','menu_days','menu_items','users','lunch_requests','invoices','invoice_flags','school_notes');
onRecordDeleteRequest(e=>{const lib=require(__hooks+'/audit-lib.js'),before=lib.snapshot(e.record);e.next();lib.write(e.app,e.record,e.auth,'delete',before,{});},'students','classrooms','daycares','substitutions','menu_days','menu_items','users','lunch_requests','invoices','invoice_flags','school_notes');
